const I=(name,size=20)=>`<svg class="ico" aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round">${iconPaths[name]||iconPaths.info}</svg>`;
const state={catalog:[],categories:[],settings:{},cart:[],search:'',suggestions:[],suggestOpen:false,menu:false,filter:false,sort:'new',filterCat:'',filterSize:'',filterColor:'',detailVariant:null,detailQty:1,admin:null,adminData:null,editing:null,adminSearch:'',searchResults:null,loading:true};
try{state.cart=JSON.parse(localStorage.getItem('lz-cart')||'[]')}catch{state.cart=[]}
function saveCart(){localStorage.setItem('lz-cart',JSON.stringify(state.cart));updateCartCount()}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3600)}
async function request(url,opts={}){
 const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(state.admin?.csrf?{'X-CSRF-Token':state.admin.csrf}:{})},...opts});
 let data;try{data=await r.json()}catch{throw Error('Resposta inesperada do servidor.')}
 if(!r.ok)throw Error(data.error||'Não foi possível completar a operação.');return data;
}
function link(href,label,cl=''){return `<a class="${cl}" href="${href}">${label}</a>`}
function navigate(path){history.pushState({},'',path);state.menu=false;state.suggestOpen=false;state.filter=false;state.detailVariant=null;state.detailQty=1;window.scrollTo(0,0);render()}
function imageBlock(p,cl='') {const src=imgUrl((p.images||[])[0]);return src?`<div class="product-visual ${cl}"><img src="${esc(src)}" alt="${esc(p.name)}" loading="lazy"/></div>`:`<div class="product-visual product-no-photo ${cl}"><span class="placeholder-mark">LZ</span><small>IMAGEM EM PREPARAÇÃO</small></div>`}
function isAvailable(p){return (p.variants||[]).some(v=>v.stock>0)}
function showPrice(p){return p.sale_cents!=null?`<span class="price-current">${money(p.sale_cents)}</span><del class="price-old">${money(p.price_cents)}</del>`:`<span class="price-current">${money(p.price_cents)}</span>`}
function card(p){return `<a href="/produto/${encodeURIComponent(p.slug)}" class="product-card" data-nav><div class="card-media">${imageBlock(p)}${!isAvailable(p)?'<span class="corner-tag">ESGOTADO</span>':''}${p.featured?'<span class="corner-tag secondary">SELEÇÃO LZ</span>':''}<span class="card-view">VER DETALHES ${I('arrow',14)}</span></div><div class="card-content"><div class="card-category">${esc(p.category?.name||'LZ COLLECTION')}</div><h3>${esc(p.name)}</h3><div class="card-price">${showPrice(p)}</div></div></a>`}
const emptyProducts=(term='')=>`<div class="empty-products">${I('bag',34)}<h3>${term?'Nenhum resultado encontrado.':'Estamos preparando a coleção.'}</h3><p>${term?'Experimente outra busca ou explore nossas categorias.':'Novas peças serão adicionadas em breve. Enquanto isso, acompanhe a LZ Collection pelo Instagram.'}</p><a href="${esc(state.settings.instagram||'https://www.instagram.com/lz.collection__/')}" target="_blank" rel="noopener" class="link-underline">ACOMPANHAR NO INSTAGRAM ${I('external',16)}</a></div>`;
function header(){return `<div class="topline"><span>${esc(state.settings.announcement||'UMA CURADORIA PARA O SEU ESTILO')}</span><span class="topline-right">MODA MASCULINA · LZ COLLECTION</span></div>
<header class="site-header"><div class="header-main wrap"><button class="icon-button mobile-menu" data-action="menu" aria-label="Abrir menu">${I('menu',23)}</button><a href="/" class="brand" data-nav aria-label="LZ Collection página inicial"><img src="/assets/mark.png" alt=""/><span class="brand-word"><strong>LZ COLLECTION</strong><em>MODA MASCULINA</em></span></a><div class="search-outer"><label class="search-box" for="site-search">${I('search',20)}<input id="site-search" type="search" placeholder="O que você está procurando?" autocomplete="off" value="${esc(state.search)}" aria-label="Buscar produtos"/><span class="search-hint">BUSCAR</span></label><div class="suggestions" id="suggestions" role="listbox"></div></div><div class="header-actions"><a class="icon-button desktop-social" href="${esc(state.settings.instagram||'#')}" target="_blank" rel="noopener" title="Instagram">${I('instagram',22)}</a><button class="icon-button cart-open" data-action="open-cart" aria-label="Abrir carrinho">${I('bag',23)}<span class="cart-count" id="cart-count">${state.cart.reduce((x,c)=>x+c.quantity,0)}</span></button></div></div><nav class="category-nav"><div class="wrap nav-scroll"><a href="/catalogo" data-nav>VER TUDO</a>${state.categories.map(c=>`<a data-nav href="/categoria/${esc(c.slug)}">${esc(c.name.toUpperCase())}</a>`).join('')}</div></nav></header>
${state.menu?`<div class="mobile-overlay" data-action="menu"></div><aside class="mobile-drawer"><div class="drawer-top"><span>EXPLORAR</span><button class="icon-button" data-action="menu">${I('close')}</button></div><a href="/catalogo" data-nav>Toda a coleção</a>${state.categories.map(c=>`<a href="/categoria/${esc(c.slug)}" data-nav>${esc(c.name)}</a>`).join('')}<a href="${esc(state.settings.instagram||'#')}" target="_blank">Instagram ${I('external',15)}</a></aside>`:''}`}
function footer(){return `<footer class="footer"><div class="wrap footer-main"><div class="footer-signature"><img src="/assets/mark.png" alt="LZ"/><strong>LZ COLLECTION</strong><span>MODA MASCULINA</span><p>${esc(state.settings.about||'Estilo, versatilidade e personalidade em cada escolha.')}</p></div><div class="footer-column"><h4>EXPLORE</h4>${state.categories.slice(0,8).map(c=>`<a href="/categoria/${esc(c.slug)}" data-nav>${esc(c.name)}</a>`).join('')}</div><div class="footer-column"><h4>FALE COM A LZ</h4><a target="_blank" rel="noopener" href="https://wa.me/${esc(state.settings.whatsapp||'5579998932703')}">WhatsApp ${I('external',14)}</a><a target="_blank" rel="noopener" href="${esc(state.settings.instagram||'#')}">Instagram ${I('external',14)}</a><a href="/privacidade" data-nav>Privacidade</a></div></div><div class="wrap footer-bottom"><span>© ${new Date().getFullYear()} LZ COLLECTION. TODOS OS DIREITOS RESERVADOS.</span><span>ESTILO EM CADA DETALHE.</span></div></footer>`}
function instaFloat(){return `<a class="instagram-float" href="${esc(state.settings.instagram||'https://www.instagram.com/lz.collection__/')}" target="_blank" rel="noopener" aria-label="Siga a LZ Collection no Instagram" title="Siga a LZ Collection no Instagram">${I('instagram',23)}</a>`}
function home(){const showcase=state.catalog.filter(p=>p.featured);const recent=[...state.catalog].sort((a,b)=>b.created_at-a.created_at).slice(0,8);
return `${header()}<main><section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><div class="eyebrow light"><span class="eyebrow-line"></span>${esc(state.settings.hero_eyebrow||'LZ COLLECTION · MODA MASCULINA')}</div><h1>${esc(state.settings.hero_title||'Presença em cada detalhe.')}</h1><p>${esc(state.settings.hero_text||'Uma curadoria de moda masculina para acompanhar a sua rotina e o seu estilo.')}</p><a class="btn btn-gold" href="/catalogo" data-nav>EXPLORAR COLEÇÃO ${I('arrow',18)}</a><div class="hero-caption">AUTENTICIDADE <span>·</span> ESTILO <span>·</span> PERSONALIDADE</div></div><div class="hero-art">${imgUrl(state.settings.hero_image)?`<img class="hero-photo" src="${esc(state.settings.hero_image)}" alt="Campanha LZ Collection"/>`:`<div class="hero-geometry"><div class="hero-ring"></div><img class="hero-monogram" src="/assets/mark.png" alt=""/><div class="hero-vertical">A SUA IDENTIDADE, O SEU ESTILO</div><span class="hero-number">EST. LZ</span></div>`}</div></div></section>
<section class="intro-bar"><div class="wrap"><span>ESTILO SEM EXCESSOS</span><div></div><span>ENCONTRE A SUA PRÓXIMA PEÇA</span><div></div><span>FINALIZE PELO WHATSAPP</span></div></section>
<section class="section wrap"><div class="section-title"><div><span class="kicker">DESCUBRA O SEU ESTILO</span><h2>Explore por categoria<span class="gold-stop">.</span></h2></div><p>Do casual ao essencial. Encontre a peça que combina com você.</p></div><div class="category-grid">${state.categories.map((c,i)=>`<a data-nav href="/categoria/${esc(c.slug)}" class="category-tile cat-${i%8}"><div class="category-pattern">${imgUrl(c.image_url)?`<img class="category-image" src="${esc(imgUrl(c.image_url))}" alt="" loading="lazy"/>`: ''}<span>${String(i+1).padStart(2,'0')}</span>${!imgUrl(c.image_url)?'<span class="tile-monogram">LZ</span>':''}</div><div class="category-name">${esc(c.name)} ${I('arrow',20)}</div></a>`).join('')}</div></section>
<section class="section section-soft"><div class="wrap"><div class="section-title"><div><span class="kicker">CURADORIA LZ</span><h2>Seleção da loja<span class="gold-stop">.</span></h2></div><a class="link-underline" href="/catalogo" data-nav>VER TODAS AS PEÇAS ${I('arrow',17)}</a></div>${(showcase.length||recent.length)?`<div class="products-grid">${(showcase.length?showcase:recent).slice(0,4).map(card).join('')}</div>`:emptyProducts()}</div></section>
<section class="editorial"><div class="wrap editorial-inner"><div class="editorial-badge">LZ / COLLECTION</div><div><div class="kicker light">A EXPERIÊNCIA LZ</div><h2>Vista sua<br/><em>melhor versão.</em></h2><p>Escolha suas peças favoritas, organize tudo no carrinho e fale diretamente com nossa equipe para confirmar disponibilidade e entrega.</p><a href="/catalogo" class="btn btn-outline" data-nav>CONHECER O CATÁLOGO ${I('arrow',17)}</a></div><img src="/assets/mark.png" alt="" class="editorial-mark"/></div></section>
${recent.length?`<section class="section wrap"><div class="section-title"><div><span class="kicker">ACABARAM DE CHEGAR</span><h2>Últimas novidades<span class="gold-stop">.</span></h2></div><a href="/catalogo" data-nav class="link-underline">EXPLORAR CATÁLOGO ${I('arrow',16)}</a></div><div class="products-grid">${recent.slice(0,4).map(card).join('')}</div></section>`:''}</main>${footer()}${instaFloat()}`}
function breadcrumb(items){return `<div class="breadcrumb">${items.map((x,i)=>i===items.length-1?`<span>${esc(x.name)}</span>`:`<a href="${x.url}" data-nav>${esc(x.name)}</a><span class="breadcrumb-slash">/</span>`).join('')}</div>`}
function listPage(){const p=location.pathname;const isCategory=p.startsWith('/categoria/');const isSearch=p==='/busca';const c=isCategory?state.categories.find(x=>x.slug===decodeURIComponent(p.split('/').pop())):null;const params=new URLSearchParams(location.search);const q=isSearch?params.get('q')||'':'';
let products=state.catalog.filter(x=>!c||x.category?.slug===c.slug||x.tags.includes(c.slug));
if(isSearch && q){products=state.searchResults||products.filter(x=>norm(x.name+' '+x.description+' '+x.keywords).includes(norm(q)))}
if(state.filterCat)products=products.filter(x=>x.category?.slug===state.filterCat||x.tags.includes(state.filterCat));
if(state.filterSize)products=products.filter(x=>x.variants.some(v=>v.stock>0 && norm(v.size)===norm(state.filterSize)));
if(state.filterColor)products=products.filter(x=>x.variants.some(v=>v.stock>0 && norm(v.color).includes(norm(state.filterColor))));
if(state.sort==='low')products.sort((a,b)=>(a.sale_cents??a.price_cents)-(b.sale_cents??b.price_cents));
if(state.sort==='high')products.sort((a,b)=>(b.sale_cents??b.price_cents)-(a.sale_cents??a.price_cents));
if(state.sort==='name')products.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
if(state.sort==='new')products.sort((a,b)=>b.created_at-a.created_at);
const heading=c?c.name:isSearch?'Resultados da busca':'A coleção';const colors=[...new Set(state.catalog.flatMap(p=>p.variants.map(v=>v.color)).filter(Boolean))].slice(0,30);const sizes=[...new Set(state.catalog.flatMap(p=>p.variants.map(v=>v.size)).filter(Boolean))];
const select=(id,placeholder,values,current)=>`<select id="${id}" aria-label="${placeholder}"><option value="">${placeholder}</option>${values.map(v=>`<option value="${esc(typeof v==='string'?v:v.slug)}" ${current===(typeof v==='string'?v:v.slug)?'selected':''}>${esc(typeof v==='string'?v:v.name)}</option>`).join('')}</select>`;
return `${header()}<main class="catalog-main"><div class="wrap">${breadcrumb([{name:'Início',url:'/'},{name:heading}])}<div class="catalog-heading"><div><div class="kicker">LZ COLLECTION / MODA MASCULINA</div><h1>${esc(heading)}<span class="gold-stop">.</span></h1>${q?`<p>Buscando por “${esc(q)}”</p>`:'<p>Encontre peças que fazem parte da sua identidade.</p>'}</div><div class="catalog-count">${products.length} ${products.length===1?'PEÇA':'PEÇAS'}</div></div><div class="filters"><div class="filter-fields">${!isCategory?select('filter-cat','Todas as categorias',state.categories,state.filterCat):''}${select('filter-size','Tamanhos',sizes,state.filterSize)}${select('filter-color','Cores',colors,state.filterColor)}</div><div class="filter-sort">${I('filter',17)} <select id="sort" aria-label="Ordenar produtos"><option value="new" ${state.sort==='new'?'selected':''}>Mais recentes</option><option value="low" ${state.sort==='low'?'selected':''}>Menor preço</option><option value="high" ${state.sort==='high'?'selected':''}>Maior preço</option><option value="name" ${state.sort==='name'?'selected':''}>Nome A–Z</option></select></div></div>${products.length?`<div class="products-grid catalog-grid">${products.map(card).join('')}</div>`:emptyProducts(q)}<div class="bottom-space"></div></div></main>${footer()}${instaFloat()}`}
function detailPage(){const key=decodeURIComponent(location.pathname.split('/').pop());const p=state.catalog.find(p=>p.slug===key);
if(!p)return notFound();const variant=state.detailVariant? p.variants.find(v=>v.id===state.detailVariant):null;const selectedImg=window.selectedDetailImg??0;const images=p.images||[];
const variantGroups=[...new Set(p.variants.map(v=>v.color).filter(Boolean))];const sizeGroups=[...new Set(p.variants.map(v=>v.size).filter(Boolean))];const related=state.catalog.filter(x=>x.id!==p.id && (x.category_id===p.category_id||x.tags.some(tag=>p.tags.includes(tag)))).slice(0,4);
return `${header()}<main><div class="wrap detail-layout">${breadcrumb([{name:'Início',url:'/'},{name:'Coleção',url:'/catalogo'},{name:p.name}])}<div class="detail-grid"><div class="detail-gallery"><div class="detail-hero-img">${images.length?`<img src="${esc(imgUrl(images[Math.min(selectedImg,images.length-1)]))}" alt="${esc(p.name)}" />` : imageBlock(p)}</div>${images.length>1?`<div class="detail-thumbs">${images.map((url,i)=>`<button data-action="detail-image" data-idx="${i}" class="${selectedImg===i?'active':''}" aria-label="Ver imagem ${i+1}"><img src="${esc(imgUrl(url))}" alt=""/></button>`).join('')}</div>`:''}</div><div class="detail-info"><div class="kicker">${esc(p.category?.name||'LZ COLLECTION')}</div><h1>${esc(p.name)}</h1><div class="detail-ref">REF. ${esc(p.sku||p.id.slice(0,8).toUpperCase())}</div><div class="detail-price">${showPrice(p)}</div><div class="thin-divider"></div>${p.description?`<p class="detail-description">${esc(p.description)}</p>`:''}<div class="stock-label ${isAvailable(p)?'in-stock':'out-stock'}"><span></span>${isAvailable(p)?'Disponível para consulta':'Produto esgotado'}</div>
<div class="detail-variation"><label>ESCOLHA SUA OPÇÃO</label><div class="variant-pills">${p.variants.map(v=>`<button data-action="variant" data-id="${v.id}" class="variant-pill ${variant?.id===v.id?'selected':''}" ${v.stock<1?'disabled':''} title="${v.stock} disponíveis">${esc([v.color,v.size].filter(Boolean).join(' · ')||'Único')}${v.stock<1?' · ESGOTADO':''}</button>`).join('')}</div></div>
<div class="qty-label">QUANTIDADE</div><div class="detail-actions"><div class="quantity-step"><button data-action="detail-qty-minus" aria-label="Diminuir">${I('minus',16)}</button><strong>${state.detailQty}</strong><button data-action="detail-qty-plus" aria-label="Aumentar">${I('plus',16)}</button></div><button class="btn btn-dark add-bag" data-action="add-cart" data-id="${p.id}" ${!isAvailable(p)?'disabled':''}>${I('bag',18)} ADICIONAR AO CARRINHO</button></div><p class="detail-footnote">Pagamento e entrega combinados diretamente com a equipe pelo WhatsApp.</p><a class="product-whatsapp" target="_blank" rel="noopener" href="https://wa.me/${esc(state.settings.whatsapp||'5579998932703')}?text=${encodeURIComponent('Olá, gostaria de saber mais sobre '+p.name+'.')}">${I('chat',17)} TIRAR DÚVIDAS SOBRE ESTA PEÇA ${I('arrow',16)}</a></div></div></div>${related.length?`<section class="section wrap related"><div class="section-title"><div><span class="kicker">VOCÊ TAMBÉM PODE GOSTAR</span><h2>Outras escolhas<span class="gold-stop">.</span></h2></div></div><div class="products-grid">${related.map(card).join('')}</div></section>`:''}</main>${footer()}${instaFloat()}`}
function cartPage(){const items=state.cart.map(x=>{const p=state.catalog.find(p=>p.id===x.product_id);const v=p?.variants.find(v=>v.id===x.variant_id);return {p,v,...x}});const subtotal=items.reduce((sum,x)=>sum+(x.p?(x.p.sale_cents??x.p.price_cents)*x.quantity:0),0);
return `${header()}<main class="wrap cart-page">${breadcrumb([{name:'Início',url:'/'},{name:'Meu carrinho'}])}<div class="catalog-heading"><div><div class="kicker">SELEÇÃO DE PEÇAS</div><h1>Meu carrinho<span class="gold-stop">.</span></h1><p>Revise suas escolhas antes de conversar com a LZ.</p></div></div>${!items.length?`<div class="empty-cart">${I('bag',45)}<h2>Seu carrinho está vazio.</h2><p>Explore a coleção e selecione as peças que combinam com você.</p><a href="/catalogo" class="btn btn-dark" data-nav>EXPLORAR A COLEÇÃO ${I('arrow',18)}</a></div>`:`<div class="cart-layout"><div class="cart-items">${items.map((x,i)=>`<div class="cart-item">${x.p?imageBlock(x.p,'cart-image'):'<div class="cart-image">REMOVIDO</div>'}<div class="cart-item-info"><span class="kicker">${esc(x.p?.category?.name||'PRODUTO')}</span><h3>${esc(x.p?.name||'Produto indisponível')}</h3><div class="muted">${esc([x.v?.color,x.v?.size].filter(Boolean).join(' · ')||'Variação indisponível')}</div><div class="cart-item-actions"><div class="quantity-step small"><button data-action="cart-minus" data-index="${i}" aria-label="Diminuir">${I('minus',15)}</button><strong>${x.quantity}</strong><button data-action="cart-plus" data-index="${i}" aria-label="Aumentar">${I('plus',15)}</button></div><button class="remove-item" data-action="cart-remove" data-index="${i}">${I('trash',16)} REMOVER</button></div></div><div class="cart-unit-price">${x.p?money((x.p.sale_cents??x.p.price_cents)*x.quantity):'—'}</div></div>`).join('')}</div><aside class="cart-summary"><span class="kicker">SUA SELEÇÃO</span><h2>Resumo</h2><div class="summary-line"><span>Itens</span><strong>${items.reduce((sum,x)=>sum+x.quantity,0)}</strong></div><div class="summary-line total"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><p>O valor final, a disponibilidade e as opções de entrega serão confirmados pela equipe.</p><button class="btn btn-dark btn-full" data-action="checkout">FINALIZAR PELO WHATSAPP ${I('arrow',18)}</button><a href="/catalogo" data-nav class="continue-shopping">${I('back',16)} CONTINUAR COMPRANDO</a></aside></div>`}</main>${footer()}${instaFloat()}`}
function privacy(){return `${header()}<main class="wrap privacy-page">${breadcrumb([{name:'Início',url:'/'},{name:'Privacidade'}])}<h1>Privacidade</h1><p>A LZ Collection utiliza armazenamento local no seu navegador para manter os itens do carrinho. Não exigimos cadastro de clientes para consultar o catálogo.</p><p>Ao clicar em “Finalizar pelo WhatsApp”, o navegador abre uma conversa com a loja contendo os itens selecionados. O envio da mensagem depende da sua confirmação no WhatsApp.</p><p>Esta é uma política inicial sobre as funcionalidades técnicas implementadas. O proprietário deverá complementar este texto com informações reais sobre tratamento de dados, canais de atendimento e direitos dos titulares antes da publicação comercial.</p></main>${footer()}${instaFloat()}`}
function notFound(){return `${header()}<main class="notfound wrap"><span>404</span><h1>Essa página não está por aqui.</h1><p>Volte para descobrir a coleção.</p><a href="/" data-nav class="btn btn-dark">VOLTAR AO INÍCIO ${I('arrow',17)}</a></main>${footer()}${instaFloat()}`}
function adminShell(content,active=''){return `<div class="admin-layout"><aside class="admin-sidebar"><a href="/" data-nav class="admin-brand"><img src="/assets/mark.png" alt="LZ"/><div><strong>LZ COLLECTION</strong><span>ADMINISTRAÇÃO</span></div></a><div class="admin-side-label">GESTÃO DA LOJA</div><nav><a href="/admin" data-nav class="${active==='home'?'active':''}">${I('grid',19)} Visão geral</a><a href="/admin/produtos" data-nav class="${active==='products'?'active':''}">${I('package',19)} Produtos</a><a href="/admin/estoque" data-nav class="${active==='stock'?'active':''}">${I('sliders',19)} Estoque</a><a href="/admin/categorias" data-nav class="${active==='categories'?'active':''}">${I('tag',19)} Categorias</a><a href="/admin/aparencia" data-nav class="${active==='appearance'?'active':''}">${I('image',19)} Aparência</a><a href="/admin/configuracoes" data-nav class="${active==='settings'?'active':''}">${I('sliders',19)} Configurações</a></nav><div class="admin-side-bottom"><span>${esc(state.admin?.email||'')}</span><button data-action="logout">${I('logout',18)} Sair</button><a href="/" target="_blank">${I('external',16)} Abrir loja</a></div></aside><div class="admin-workspace"><div class="admin-topbar"><span>LZ / PAINEL</span><button data-action="logout">${I('logout',16)} SAIR</button></div>${content}</div></div>`}
function adminLogin(){return `<div class="admin-login"><div class="admin-login-art"><img src="/assets/mark.png" alt="LZ Collection"/><span>LZ COLLECTION</span><small>MODA MASCULINA</small><h1>A sua loja, nas suas mãos.</h1><p>Gerencie o catálogo e mantenha a vitrine sempre atualizada.</p></div><div class="admin-login-form"><a href="/" data-nav class="back-store">${I('back',17)} VOLTAR À LOJA</a><div class="kicker">ACESSO RESTRITO</div><h2>Bem-vindo de volta.</h2><p>Entre com sua conta de proprietário para administrar a loja.</p><form id="login-form" class="form-stack"><label>E-MAIL<input type="email" name="email" autocomplete="username" required placeholder="seu@email.com"/></label><label>SENHA<input type="password" name="password" autocomplete="current-password" required placeholder="Sua senha"/></label><button class="btn btn-dark btn-full">ACESSAR PAINEL ${I('arrow',17)}</button><p class="form-error" id="login-error" aria-live="polite"></p></form><small>Apenas contas autorizadas têm acesso à administração.</small></div></div>`}
function adminOverview(){const ps=state.adminData.products,qty=ps.filter(p=>p.stock<=0).length,low=ps.filter(p=>p.stock>0&&p.stock<=3).length,live=ps.filter(p=>p.published).length;
return adminShell(`<section class="admin-page"><div class="admin-page-head"><div><div class="kicker">PAINEL DE CONTROLE</div><h1>Visão geral</h1><p>Uma visão rápida da sua vitrine.</p></div><a href="/admin/produtos/novo" class="btn btn-dark" data-nav>${I('plus',17)} NOVO PRODUTO</a></div><div class="admin-kpis"><div><span>PRODUTOS CADASTRADOS</span><strong>${ps.length}</strong><small>Total no catálogo</small></div><div><span>PRODUTOS PUBLICADOS</span><strong>${live}</strong><small>Visíveis na loja</small></div><div><span>PRODUTOS ESGOTADOS</span><strong>${qty}</strong><small>Sem unidades</small></div><div><span>ESTOQUE BAIXO</span><strong>${low}</strong><small>Até 3 unidades</small></div></div><div class="admin-panel"><div class="admin-panel-head"><h2>Últimos produtos</h2><a href="/admin/produtos" data-nav>GERENCIAR TODOS ${I('arrow',16)}</a></div>${adminProductTable(ps.slice(0,6))}</div><div class="admin-tip">${I('info',19)} <span>As vendas são confirmadas pelo WhatsApp. Atualize o estoque manualmente após cada venda.</span></div></section>`,'home')}
function adminProductTable(ps){return ps.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>PRODUTO</th><th>PREÇO</th><th>ESTOQUE</th><th>STATUS</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="admin-product-cell">${(p.images||[]).length?`<img src="${esc(imgUrl(p.images[0]))}" alt=""/>`:`<div class="admin-thumb">LZ</div>`}<div><strong>${esc(p.name)}</strong><small>${esc(p.sku||p.category?.name||'Sem referência')}</small></div></div></td><td>${money(p.sale_cents??p.price_cents)}</td><td>${p.stock}</td><td><span class="admin-status ${p.published?'live':'draft'}">${p.published?'Publicado':'Rascunho'}</span></td><td><a href="/admin/produtos/${p.id}/editar" data-nav class="admin-edit">${I('edit',17)} EDITAR</a></td></tr>`).join('')}</tbody></table></div>`:'<div class="admin-empty">Seu catálogo está vazio. Comece cadastrando a primeira peça.</div>'}
function adminProducts(){let ps=state.adminData.products.filter(p=>norm(p.name+' '+p.sku).includes(norm(state.adminSearch)));
return adminShell(`<section class="admin-page"><div class="admin-page-head"><div><div class="kicker">CATÁLOGO / ADMINISTRAÇÃO</div><h1>Produtos</h1><p>Cadastre e mantenha suas peças atualizadas.</p></div><a href="/admin/produtos/novo" data-nav class="btn btn-dark">${I('plus',17)} ADICIONAR PEÇA</a></div><div class="admin-panel"><div class="admin-filter-line"><label class="admin-search">${I('search',18)}<input id="admin-search" placeholder="Pesquisar nome ou referência..." value="${esc(state.adminSearch)}"/></label><span>${ps.length} produtos</span></div>${adminProductTable(ps)}</div></section>`,'products')}
const formField=(name,label,value='',type='text',attr='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attr}/></label>`;
function adminEditor(){const p=state.editing||{name:'',sku:'',description:'',keywords:'',price_cents:0,sale_cents:null,category_id:'',tags:[],images:[],variants:[{color:'',size:'',sku:'',stock:0}],published:false,featured:false};const isNew=!state.editing?.id;
return adminShell(`<section class="admin-page admin-edit-page"><div class="admin-page-head"><div><a class="back-store" href="/admin/produtos" data-nav>${I('back',17)} VOLTAR AOS PRODUTOS</a><div class="kicker">${isNew?'NOVO PRODUTO':'EDIÇÃO DE PRODUTO'}</div><h1>${isNew?'Cadastrar peça':'Editar peça'}</h1></div></div><form id="product-form"><div class="admin-edit-grid"><div><div class="admin-panel edit-panel"><h2>Informações da peça</h2><div class="form-grid">${formField('name','NOME DO PRODUTO',p.name,'text','required maxlength="180"')}${formField('sku','REFERÊNCIA / SKU',p.sku||'')}</div><label class="admin-label">DESCRIÇÃO<textarea name="description" rows="4" placeholder="Descreva o tecido, caimento e características...">${esc(p.description||'')}</textarea></label><div class="form-grid"><label>CATEGORIA PRINCIPAL<select name="category_id"><option value="">Selecione</option>${state.adminData.categories.map(c=>`<option value="${c.id}" ${Number(p.category_id)===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>${formField('keywords','TERMOS PARA A BUSCA',p.keywords||'')}</div><div class="admin-label">APARECER TAMBÉM EM</div><div class="tag-checks">${state.adminData.categories.map(c=>`<label><input type="checkbox" name="tag" value="${esc(c.slug)}" ${(p.tags||[]).includes(c.slug)?'checked':''}/> ${esc(c.name)}</label>`).join('')}</div></div>
<div class="admin-panel edit-panel"><h2>Valores e visibilidade</h2><div class="form-grid">${formField('price','PREÇO (R$)',(p.price_cents/100).toFixed(2),'number','step="0.01" min="0" required')}${formField('sale','PREÇO PROMOCIONAL (R$)',p.sale_cents==null?'':(p.sale_cents/100).toFixed(2),'number','step="0.01" min="0"')}</div><div class="admin-switches"><label><input type="checkbox" name="published" ${p.published?'checked':''}/> PUBLICAR NA VITRINE</label><label><input type="checkbox" name="featured" ${p.featured?'checked':''}/> MOSTRAR NA SELEÇÃO LZ</label></div></div>
<div class="admin-panel edit-panel"><div class="admin-panel-head"><h2>Tamanhos, cores e estoque</h2><button class="admin-text-btn" type="button" data-action="variant-add">${I('plus',16)} ADICIONAR VARIAÇÃO</button></div><p>Uma linha por combinação de cor e tamanho. Se a peça não tiver variações, use tamanho "Único".</p><div id="variants-container">${variantRows(p.variants)}</div></div></div>
<aside><div class="admin-panel edit-panel"><h2>Fotografias</h2><p>Envie fotos reais das peças. A primeira foto será a capa.</p><label class="upload-zone" for="image-input">${I('upload',25)}<strong>Adicionar fotos</strong><span>JPG, PNG ou WebP · até 6 MB</span></label><input type="file" id="image-input" accept="image/jpeg,image/png,image/webp" multiple hidden/><div id="image-list" class="admin-image-list">${(p.images||[]).map((u,i)=>`<div class="admin-image"><img src="${esc(imgUrl(u))}" alt="Foto ${i+1}"/><button type="button" data-action="image-remove" data-index="${i}" aria-label="Remover imagem">${I('close',16)}</button></div>`).join('')}</div><small>As alterações serão salvas ao clicar em Salvar produto.</small></div><div class="admin-save-panel"><button type="submit" class="btn btn-dark btn-full">${I('check',18)} SALVAR PRODUTO</button>${!isNew?`<button class="danger-text" data-action="delete-product" type="button" data-id="${p.id}">${I('trash',17)} EXCLUIR PRODUTO</button>`:''}</div></aside></div></form></section>`,'products')}
function variantRows(variants){return (variants||[]).map((v,i)=>`<div class="variant-row" data-vindex="${i}"><label>COR<input value="${esc(v.color||'')}" data-vfield="color" placeholder="Preto" /></label><label>TAMANHO<input value="${esc(v.size||'')}" data-vfield="size" placeholder="M ou 42" /></label><label>REFERÊNCIA<input value="${esc(v.sku||'')}" data-vfield="sku" placeholder="SKU" /></label><label>ESTOQUE<input type="number" min="0" value="${v.stock||0}" data-vfield="stock" /></label><button type="button" data-action="variant-remove" data-index="${i}" title="Remover variação">${I('close',17)}</button></div>`).join('')}
function syncEditor(){if(!state.editing)state.editing={variants:[{color:'',size:'',sku:'',stock:0}],images:[]};const form=$('#product-form');if(!form)return;const fd=new FormData(form);const old=state.editing;state.editing={...old,name:fd.get('name'),sku:fd.get('sku'),description:fd.get('description'),keywords:fd.get('keywords'),category_id:Number(fd.get('category_id'))||null,price_cents:Math.round(Number(fd.get('price'))*100),sale_cents:fd.get('sale')===''?null:Math.round(Number(fd.get('sale'))*100),tags:fd.getAll('tag'),published:fd.has('published'),featured:fd.has('featured'),variants:$$('.variant-row').map(el=>({color:$('[data-vfield="color"]',el).value,size:$('[data-vfield="size"]',el).value,sku:$('[data-vfield="sku"]',el).value,stock:Number($('[data-vfield="stock"]',el).value)}))}}
function adminStock(){const ps=state.adminData.products;return adminShell(`<section class="admin-page"><div class="admin-page-head"><div><div class="kicker">DISPONIBILIDADE</div><h1>Estoque</h1><p>Atualize as quantidades pelo cadastro de cada peça.</p></div></div><div class="admin-panel"><div class="admin-panel-head"><h2>Produtos e unidades</h2></div>${ps.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>PRODUTO</th><th>VARIAÇÕES</th><th>DISPONÍVEL</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><strong>${esc(p.name)}</strong></td><td>${p.variants.map(v=>`<span class="mini-variant">${esc([v.color,v.size].filter(Boolean).join(' / ')||'Único')}: <b>${v.stock}</b></span>`).join('')}</td><td><span class="admin-status ${p.stock>0?'live':'draft'}">${p.stock>0?p.stock+' unidades':'ESGOTADO'}</span></td><td><a class="admin-edit" href="/admin/produtos/${p.id}/editar" data-nav>${I('edit',16)} AJUSTAR</a></td></tr>`).join('')}</tbody></table></div>`:'<div class="admin-empty">Nenhum produto cadastrado.</div>'}</div><div class="admin-tip">${I('info',18)} O estoque é atualizado manualmente após a confirmação das vendas no WhatsApp.</div></section>`,'stock')}
function adminCategories(){return adminShell(`<section class="admin-page"><div class="admin-page-head"><div><div class="kicker">ORGANIZAÇÃO DA VITRINE</div><h1>Categorias</h1><p>Defina nomes, capas e visibilidade das seções da loja.</p></div><button class="btn btn-dark" data-action="category-add">${I('plus',17)} NOVA CATEGORIA</button></div><form id="categories-form" class="admin-panel edit-panel"><div class="admin-panel-head"><h2>Suas categorias</h2></div><div class="category-admin-list">${state.adminData.categories.map((c,i)=>`<div class="category-admin-row" data-catid="${c.id||0}"><div class="category-admin-picture">${imgUrl(c.image_url)?`<img src="${esc(imgUrl(c.image_url))}" alt="Capa"/>`:I('image',23)}</div><div class="category-fields"><label>NOME<input class="cat-name" aria-label="Nome da categoria" value="${esc(c.name)}" required/></label><label>DESCRIÇÃO<input class="cat-description" aria-label="Descrição da categoria" value="${esc(c.description||'')}" placeholder="Opcional"/></label><div class="category-actions"><label class="category-upload">${I('upload',15)} TROCAR CAPA<input type="file" data-category-image accept="image/jpeg,image/png,image/webp" hidden/></label><label class="category-visibility"><input class="cat-active" type="checkbox" ${c.active?'checked':''}/> VISÍVEL</label></div><input type="hidden" class="cat-image" value="${esc(c.image_url||'')}"/></div></div>`).join('')}</div><button class="btn btn-dark" type="submit">${I('check',18)} SALVAR CATEGORIAS</button><p class="admin-note">Uma mesma peça pode aparecer em várias seções usando as etiquetas adicionais no cadastro do produto.</p></form></section>`,'categories')}
function readCategoriesForm(){return $$('.category-admin-row').map(row=>({id:Number(row.dataset.catid),name:$('.cat-name',row).value,description:$('.cat-description',row).value,image_url:$('.cat-image',row).value,active:$('.cat-active',row).checked}))}

function adminSettings(appearance){const s=state.adminData.settings;
return adminShell(`<section class="admin-page"><div class="admin-page-head"><div><div class="kicker">PERSONALIZAÇÃO</div><h1>${appearance?'Aparência da loja':'Configurações'}</h1><p>${appearance?'Atualize a comunicação visual da página inicial.':'Mantenha os contatos oficiais e as informações da loja.'}</p></div></div><form id="settings-form" class="admin-panel edit-panel settings-form">${appearance?`<h2>Banner e comunicação</h2>${formField('hero_eyebrow','LINHA DE APOIO',s.hero_eyebrow)}${formField('hero_title','TÍTULO PRINCIPAL',s.hero_title)}<label>TEXTO DO BANNER<textarea name="hero_text" rows="3">${esc(s.hero_text)}</textarea></label>${formField('announcement','AVISO SUPERIOR',s.announcement)}<label>IMAGEM DO BANNER (OPCIONAL)</label><p class="admin-note">Sem imagem, o banner exibe o monograma original com composição editorial.</p><input type="hidden" name="hero_image" value="${esc(s.hero_image)}"/><label class="upload-zone" for="banner-input">${I('upload',23)}<strong>Substituir imagem do banner</strong><span>JPG, PNG ou WebP</span></label><input type="file" id="banner-input" accept="image/png,image/jpeg,image/webp" hidden/>${imgUrl(s.hero_image)?`<img class="banner-preview" src="${esc(imgUrl(s.hero_image))}" alt="Banner atual"/>`:''}<label>DESCRIÇÃO INSTITUCIONAL<textarea name="about" rows="2">${esc(s.about||'')}</textarea></label>`:`<h2>Contato e redes</h2>${formField('whatsapp','WHATSAPP COM DDI + DDD',s.whatsapp,'tel','required')}${formField('instagram','LINK DO INSTAGRAM',s.instagram,'url','required')}<div class="admin-tip">${I('shield',18)} Os dados desta seção são usados em todos os links de contato da vitrine.</div>`}<button class="btn btn-dark" type="submit">${I('check',17)} SALVAR ALTERAÇÕES</button></form></section>`,appearance?'appearance':'settings')}
async function loadAdmin(){try{const me=await request('/api/admin/me');state.admin=me;const r=await request('/api/admin/data');state.adminData=r;return true}catch{state.admin=null;state.adminData=null;return false}}
async function render(){const path=location.pathname;const app=$('#app');document.body.classList.toggle('admin-body',path.startsWith('/admin'));
if(path.startsWith('/admin')){
 if(!state.adminData){app.innerHTML='<div class="loading-screen">LZ COLLECTION <span>CARREGANDO PAINEL...</span></div>';let ok=await loadAdmin();if(!ok){app.innerHTML=adminLogin();return}}
 if(path==='/admin/login'){navigate('/admin');return}
 if(path==='/admin')app.innerHTML=adminOverview();
 else if(path==='/admin/produtos')app.innerHTML=adminProducts();
 else if(path==='/admin/estoque')app.innerHTML=adminStock();
 else if(path==='/admin/categorias')app.innerHTML=adminCategories();
 else if(path==='/admin/aparencia')app.innerHTML=adminSettings(true);
 else if(path==='/admin/configuracoes')app.innerHTML=adminSettings(false);
 else if(path==='/admin/produtos/novo'){if(!state.editing)state.editing={variants:[{color:'',size:'Único',sku:'',stock:0}],images:[]};app.innerHTML=adminEditor()}
 else if(path.match(/^\/admin\/produtos\/[^/]+\/editar$/)){const id=path.split('/')[3];if(!state.editing||state.editing.id!==id)state.editing=structuredClone(state.adminData.products.find(p=>p.id===id));app.innerHTML=state.editing?adminEditor():adminProducts()}
 else app.innerHTML=adminOverview();
 } else if(path==='/')app.innerHTML=home();
 else if(path==='/catalogo'||path==='/busca'||path.startsWith('/categoria/')){if(path==='/busca'){const qry=new URLSearchParams(location.search).get('q')||'';try{state.searchResults=(await request('/api/products?q='+encodeURIComponent(qry)+'&limit=500')).products}catch{state.searchResults=[]}}app.innerHTML=listPage()}
 else if(path.startsWith('/produto/'))app.innerHTML=detailPage();
 else if(path==='/carrinho')app.innerHTML=cartPage();
 else if(path==='/privacidade')app.innerHTML=privacy();
 else app.innerHTML=notFound();updateCartCount();}
function updateCartCount(){const el=$('#cart-count');if(el)el.textContent=state.cart.reduce((sum,x)=>sum+x.quantity,0)}
function updateSuggestions(){const el=$('#suggestions');if(!el)return;const q=state.search.trim();if(!q||!state.suggestOpen){el.classList.remove('visible');el.innerHTML='';return}el.classList.add('visible');let suggestions=state.suggestions;el.innerHTML=`<div class="suggest-heading">SUGESTÕES PARA “${esc(q)}”</div>${suggestions.length?suggestions.slice(0,5).map(p=>`<a href="/produto/${esc(p.slug)}" data-nav role="option"><div class="suggest-img">${(p.images||[]).length?`<img src="${esc(imgUrl(p.images[0]))}" alt=""/>`:'<span>LZ</span>'}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.category?.name||'LZ COLLECTION')}</small></div><span class="suggest-price">${money(p.sale_cents??p.price_cents)}</span></a>`).join(''):`<div class="suggest-empty">Nenhuma peça encontrada. Tente outra palavra.</div>`}<a class="suggest-all" href="/busca?q=${encodeURIComponent(q)}" data-nav>VER RESULTADOS COMPLETOS ${I('arrow',16)}</a>`}
let searchTimer;document.addEventListener('input',e=>{
 if(e.target.id==='site-search'){state.search=e.target.value;state.suggestOpen=true;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{if(!state.search.trim()){state.suggestions=[];updateSuggestions();return}try{const res=await request('/api/products?q='+encodeURIComponent(state.search)+'&limit=6');state.suggestions=res.products;updateSuggestions()}catch{}},230)}
 if(e.target.id==='admin-search'){state.adminSearch=e.target.value;const el=$('.admin-table-wrap');if(el){const p=state.adminData.products.filter(p=>norm(p.name+' '+p.sku).includes(norm(state.adminSearch)));el.outerHTML=adminProductTable(p)}}
});
document.addEventListener('focusin',e=>{if(e.target.id==='site-search'){state.suggestOpen=true;updateSuggestions()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){state.suggestOpen=false;updateSuggestions()}if(e.key==='Enter'&&e.target.id==='site-search'){e.preventDefault();navigate('/busca?q='+encodeURIComponent(state.search.trim()))}});
document.addEventListener('click',async e=>{
 const anchor=e.target.closest('a[data-nav]');if(anchor){e.preventDefault();state.editing=null;window.selectedDetailImg=0;navigate(new URL(anchor.href).pathname+new URL(anchor.href).search);return}
 const b=e.target.closest('[data-action]');if(!b){if(!e.target.closest('.search-outer')){state.suggestOpen=false;updateSuggestions()}return}
 const action=b.dataset.action;
 if(action==='menu'){state.menu=!state.menu;render();return}
 if(action==='open-cart'){navigate('/carrinho');return}
 if(action==='variant'){state.detailVariant=b.dataset.id;state.detailQty=1;render();return}
 if(action==='detail-image'){window.selectedDetailImg=Number(b.dataset.idx);render();return}
 if(action==='detail-qty-minus'){state.detailQty=Math.max(1,state.detailQty-1);render();return}
 if(action==='detail-qty-plus'){state.detailQty=Math.min(99,state.detailQty+1);render();return}
 if(action==='add-cart'){const p=state.catalog.find(x=>x.id===b.dataset.id);if(!p)return;let v=p.variants.find(x=>x.id===state.detailVariant);if(!v&&p.variants.length===1)v=p.variants[0];if(!v){toast('Selecione uma cor e um tamanho antes de continuar.');return}const existing=state.cart.find(x=>x.product_id===p.id&&x.variant_id===v.id);if((existing?.quantity||0)+state.detailQty>v.stock){toast('Não há unidades suficientes em estoque.');return}if(existing)existing.quantity+=state.detailQty;else state.cart.push({product_id:p.id,variant_id:v.id,quantity:state.detailQty});saveCart();toast('Peça adicionada ao carrinho.');return}
 if(action.startsWith('cart-')){const i=Number(b.dataset.index),x=state.cart[i];if(!x)return;const p=state.catalog.find(p=>p.id===x.product_id),v=p?.variants.find(v=>v.id===x.variant_id);if(action==='cart-remove')state.cart.splice(i,1);if(action==='cart-minus'){x.quantity--;if(x.quantity<=0)state.cart.splice(i,1)}if(action==='cart-plus'){if(!v||x.quantity>=v.stock){toast('Quantidade indisponível no estoque.');return}x.quantity++}saveCart();render();return}
 if(action==='checkout'){
  const checkoutTab=window.open('about:blank','_blank'); if(checkoutTab)checkoutTab.opener=null;
  b.disabled=true;b.textContent='CONFERINDO DISPONIBILIDADE...';try{
   const r=await request('/api/validate',{method:'POST',body:JSON.stringify({items:state.cart})});
   if(!r.valid){if(checkoutTab)checkoutTab.close();toast(r.errors[0]||'Revise seu carrinho antes de finalizar.');await init();return}
   let msg='Olá, LZ Collection! Gostaria de consultar a disponibilidade e finalizar a compra destas peças:\n\n'+r.items.map((x,i)=>`${i+1}. ${x.name}\nReferência: ${x.sku||'—'}\nCor: ${x.color||'—'}\nTamanho: ${x.size||'Único'}\nQuantidade: ${x.quantity}\nValor: ${money(x.price_cents*x.quantity)}`).join('\n\n')+`\n\nSubtotal estimado: ${money(r.subtotal_cents)}\n\nGostaria de confirmar a disponibilidade, pagamento e entrega.`;
   const whatsappUrl=`https://wa.me/${state.settings.whatsapp||'5579998932703'}?text=${encodeURIComponent(msg)}`;
   if(checkoutTab)checkoutTab.location.replace(whatsappUrl); else window.location.href=whatsappUrl;
   toast('O WhatsApp foi aberto. Envie a mensagem para concluir a solicitação.');
  }catch(err){if(checkoutTab)checkoutTab.close();toast(err.message)}finally{b.disabled=false;b.innerHTML=`FINALIZAR PELO WHATSAPP ${I('arrow',18)}`}return
 }
 if(action==='logout'){try{await request('/api/auth/logout',{method:'POST',body:'{}'})}catch{}state.admin=null;state.adminData=null;state.editing=null;navigate('/admin/login');return}
 if(action==='category-add'){state.adminData.categories=[...readCategoriesForm(),{id:0,name:'Nova categoria',description:'',image_url:'',active:true}];render();return}
 if(action==='variant-add'){syncEditor();state.editing.variants.push({color:'',size:'',sku:'',stock:0});render();return}
 if(action==='variant-remove'){syncEditor();state.editing.variants.splice(Number(b.dataset.index),1);render();return}
 if(action==='image-remove'){syncEditor();state.editing.images.splice(Number(b.dataset.index),1);render();return}
 if(action==='delete-product'){
  if(!confirm('Deseja realmente excluir esta peça e suas variações? Esta ação é permanente.'))return;
  try{await request('/api/admin/products/'+b.dataset.id,{method:'DELETE'});state.editing=null;state.adminData=null;await loadAdmin();navigate('/admin/produtos');toast('Produto excluído.')}catch(err){toast(err.message)}return
 }
});
document.addEventListener('change',async e=>{
 if(['filter-cat','filter-size','filter-color','sort'].includes(e.target.id)){state[e.target.id==='sort'?'sort':e.target.id==='filter-cat'?'filterCat':e.target.id==='filter-size'?'filterSize':'filterColor']=e.target.value;render();return}
 if(e.target.matches('[data-category-image]')){const row=e.target.closest('.category-admin-row');const file=e.target.files?.[0];if(!file)return;if(file.size>6*1024*1024){toast('Imagem muito grande.');return}try{const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file)});const result=await request('/api/admin/upload',{method:'POST',body:JSON.stringify({data})});$('.cat-image',row).value=result.url;$('.category-admin-picture',row).innerHTML=`<img src="${esc(result.url)}" alt="Capa"/>`;toast('Capa enviada. Clique em Salvar categorias.')}catch(err){toast(err.message)}return}
 if(e.target.id==='image-input'||e.target.id==='banner-input'){
  const isBanner=e.target.id==='banner-input';if(!isBanner)syncEditor();const files=Array.from(e.target.files||[]);
  for(const file of files){if(file.size>6*1024*1024){toast('Cada imagem deve ter no máximo 6MB.');continue}
   try{const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file)});const result=await request('/api/admin/upload',{method:'POST',body:JSON.stringify({data})});if(isBanner){const input=$('input[name="hero_image"]');if(input)input.value=result.url;toast('Imagem enviada. Clique em Salvar alterações.')}else{state.editing.images.push(result.url);toast('Imagem enviada. Salve o produto.')}}catch(err){toast(err.message)}
  }if(!isBanner)render();return;
 }
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['login-form','product-form','categories-form','settings-form'].includes(form.id))return;e.preventDefault();const btn=$('button[type=submit]',form);if(btn)btn.disabled=true;
 try{
  if(form.id==='login-form'){
   const data=Object.fromEntries(new FormData(form));const result=await request('/api/auth/login',{method:'POST',body:JSON.stringify(data)});state.admin=result;state.adminData=null;await loadAdmin();navigate('/admin');toast('Bem-vindo ao painel da loja.');return
  }
  if(form.id==='product-form'){
   syncEditor();const p=state.editing;const create=!p.id;const endpoint=create?'/api/admin/products':'/api/admin/products/'+p.id;
   if(!p.name?.trim())throw Error('Informe o nome da peça.');if(p.variants.some(v=>v.stock<0))throw Error('Estoque não pode ser negativo.');
   await request(endpoint,{method:create?'POST':'PUT',body:JSON.stringify(p)});state.editing=null;state.adminData=null;await loadAdmin();navigate('/admin/produtos');toast('Produto salvo com sucesso.');return
  }
  if(form.id==='categories-form'){
   const categories=readCategoriesForm();await request('/api/admin/categories',{method:'PUT',body:JSON.stringify({categories})});state.adminData=null;await loadAdmin();await init(false);toast('Categorias atualizadas.');return
  }
  if(form.id==='settings-form'){
   const data=Object.fromEntries(new FormData(form));await request('/api/admin/settings',{method:'PUT',body:JSON.stringify(data)});state.adminData=null;await loadAdmin();await init(false);toast('Configurações atualizadas.');return
  }
 }catch(err){const error=$('#login-error');if(error)error.textContent=err.message;else toast(err.message)}finally{if(btn)btn.disabled=false}
});
window.addEventListener('popstate',()=>{state.editing=null;render()});
async function init(showLoading=true){if(showLoading)$('#app').innerHTML='<div class="loading-screen"><img src="/assets/mark.png" alt="LZ"/><strong>LZ COLLECTION</strong><span>MODA MASCULINA</span></div>';try{const result=await request('/api/catalog?limit=500');state.catalog=result.products;state.categories=result.categories;state.settings=result.settings;state.loading=false;await render()}catch(err){$('#app').innerHTML=`<div class="offline-message"><h1>LZ COLLECTION</h1><p>Não foi possível carregar o catálogo.</p><button onclick="location.reload()">TENTAR NOVAMENTE</button><small>${esc(err.message)}</small></div>`}}
init();
